import assert from "node:assert/strict";
import type { InputTransformerFn } from "orval";

/*
 * Corrections to the backend's OpenAPI spec (`openapi.json`), applied by Orval before it generates the API client.
 *
 * The spec is generated by ASP.NET and doesn't match what the backend actually sends and accepts in a few places.
 * Every correction first asserts the exact shape it replaces, so generation fails if the backend contract changes
 * instead of the change being silently overwritten. When that happens, check the backend and update the correction.
 *
 * `correctBackendContract` describes verified backend behavior. `addFrontendRequirements` makes the contract stricter
 * than the backend where the frontend relies on it, and is kept separate so it isn't mistaken for backend behavior.
 */

type JsonObject = Record<string, unknown>;

const isObject = (value: unknown): value is JsonObject =>
	typeof value === "object" && value !== null && !Array.isArray(value);

function at(root: unknown, ...path: Array<string>): JsonObject {
	let node = root;
	for (const [index, key] of path.entries()) {
		assert.ok(isObject(node), `Expected an object at ${path.slice(0, index).join(".") || "the root"}`);
		node = node[key];
	}
	assert.ok(isObject(node), `Expected an object at ${path.join(".")}`);
	return node;
}

function walk(node: unknown, visit: (object: JsonObject) => void) {
	if (Array.isArray(node)) {
		for (const child of node) {
			walk(child, visit);
		}
	} else if (isObject(node)) {
		visit(node);
		for (const child of Object.values(node)) {
			walk(child, visit);
		}
	}
}

const schemaRef = (name: string) => ({ $ref: `#/components/schemas/${name}` });

const jsonSchema = (spec: unknown, path: string, verb: string, part: "requestBody" | "response") =>
	part === "requestBody"
		? at(spec, "paths", path, verb, "requestBody", "content", "application/json")
		: at(spec, "paths", path, verb, "responses", "200", "content", "application/json");

/** Readable function names for the generated client. ASP.NET doesn't emit operation IDs. */
const OPERATION_IDS: Record<string, string> = {
	"get /api/users": "getUsers",
	"post /api/users": "createUser",
	"get /api/users/{id}": "getUser",
	"put /api/users/{id}": "updateUser",
	"delete /api/users/{id}": "deleteUser",
	"get /api/users/{managerId}/subordinates": "getSubordinates",
	"get /api/users/{managerId}/subordinates/threshold-summary": "getThresholdSummary",
	"put /api/users/{managerId}/subordinates/delete": "removeSubordinates",
	"put /api/users/{managerId}/subordinates/create": "addSubordinates",
	"post /api/notes/{userId}": "getNotes",
	"put /api/notes/{userId}": "updateNote",
	"delete /api/notes/{userId}": "deleteNote",
	"post /api/notes/{userId}/create": "createNote",
	"post /api/exposure/{exposureType}/{userId}": "getExposureData",
	"post /api/exposure/overview/{userId}": "getExposureOverview",
};

/**
 * The backend serializes enums as camelCase strings (`JsonStringEnumConverter(JsonNamingPolicy.CamelCase)` in
 * Program.cs), but registers the converter for MVC only, so the spec declares them as integers. The values are the
 * C# enum members in camelCase.
 */
const STRING_ENUMS: Record<string, Array<string>> = {
	UserRole: ["operator", "foreman"],
	DangerLevel: ["safe", "warning", "danger"],
	ExposureType: ["noise", "vibration", "dust"],
	TimeGranularity: ["minute", "hour", "day"],
	AggregationFunction: ["avg", "sum", "min", "max", "count"],
	Field: ["pm1_stel", "pm25_stel", "pm4_stel", "pm10_stel", "pm1_twa", "pm25_twa", "pm4_twa", "pm10_twa"],
};

/**
 * Schemas the backend only sends in responses (`NoteDataDto` is also a request body). System.Text.Json writes every
 * property, since Program.cs sets no `DefaultIgnoreCondition`, so all of their properties are always present.
 */
const RESPONSE_SCHEMAS = [
	"UserDto",
	"UserWithStatusDto",
	"LocationDto",
	"UserStatusDto",
	"UserExposureStatusDto",
	"ExposureResponseDto",
	"ExposureDataDto",
	"HourDomainDto",
	"CombinedExposureBucketDto",
	"ExposureThresholdSummaryDto",
	"NoteDataDto",
];

const GUID_PATTERN = "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$";

/** Names of the component schemas referenced from the responses, directly or through other schemas */
function responseSchemaNames(spec: unknown): Array<string> {
	const schemas = at(spec, "components", "schemas");
	const found = new Set<string>();
	const visit = (node: unknown) =>
		walk(node, (child) => {
			if (typeof child.$ref === "string") {
				const name = child.$ref.replace("#/components/schemas/", "");
				if (!found.has(name)) {
					found.add(name);
					visit(schemas[name]);
				}
			}
		});
	for (const item of Object.values(at(spec, "paths"))) {
		assert.ok(isObject(item));
		for (const operation of Object.values(item)) {
			assert.ok(isObject(operation));
			visit(operation.responses);
		}
	}
	return [...found].filter((name) => !(name in STRING_ENUMS)).sort();
}

function correctBackendContract(spec: unknown) {
	const schemas = at(spec, "components", "schemas");
	const paths = at(spec, "paths");

	assert.deepEqual(
		responseSchemaNames(spec),
		[...RESPONSE_SCHEMAS].sort(),
		"The backend spec's response schemas changed: update RESPONSE_SCHEMAS in openapi/corrections.ts",
	);

	const seenOperations = new Set<string>();
	for (const [path, item] of Object.entries(paths)) {
		for (const [verb, operation] of Object.entries(at(paths, path))) {
			const key = `${verb} ${path}`;
			assert.ok(key in OPERATION_IDS, `New endpoint ${key}: give it an operation ID in openapi/corrections.ts`);
			assert.ok(isObject(operation) && isObject(item));
			assert.equal(operation.operationId, undefined, `${key} now has an operation ID in the backend spec`);
			operation.operationId = OPERATION_IDS[key];
			seenOperations.add(key);
		}
	}
	for (const key of Object.keys(OPERATION_IDS)) {
		assert.ok(seenOperations.has(key), `Endpoint ${key} was removed from the backend spec`);
	}

	for (const [name, values] of Object.entries(STRING_ENUMS)) {
		assert.deepEqual(schemas[name], { type: "integer" }, `The backend spec changed enum ${name}`);
		schemas[name] = { type: "string", enum: values };
	}

	// ASP.NET documents `NumberHandling.AllowReadingFromString` for numbers, but the backend always writes numbers
	let numericFields = 0;
	walk(schemas, (node) => {
		if (Array.isArray(node.type) && node.type.includes("string") && typeof node.pattern === "string") {
			const types = node.type.filter((type) => type !== "string");
			if (types.includes("number") || types.includes("integer")) {
				node.type = types.length === 1 ? types[0] : types;
				delete node.pattern;
				numericFields++;
			}
		}
	});
	assert.ok(numericFields > 0, "The backend spec no longer declares numbers as `number | string`");

	for (const name of RESPONSE_SCHEMAS) {
		const schema = at(schemas, name);
		schema.required = Object.keys(at(schema, "properties"));
	}

	// ExposureDataController.GetOverviewData declares `IEnumerable<CombinedExposureBucketDto>` but returns an
	// `ExposureOverviewResponse`
	const overviewResponse = jsonSchema(spec, "/api/exposure/overview/{userId}", "post", "response");
	assert.deepEqual(
		overviewResponse.schema,
		{ type: "array", items: schemaRef("CombinedExposureBucketDto") },
		"The backend spec changed the exposure overview response",
	);
	schemas.ExposureOverviewResponseDto = {
		type: "object",
		required: ["data", "hourDomain"],
		properties: {
			data: { type: "array", items: schemaRef("CombinedExposureBucketDto") },
			hourDomain: schemaRef("HourDomainDto"),
		},
	};
	overviewResponse.schema = schemaRef("ExposureOverviewResponseDto");

	// Named, because Orval generates a type name for this inline record body that doesn't match the exported type
	const overviewRequest = jsonSchema(spec, "/api/exposure/overview/{userId}", "post", "requestBody");
	assert.deepEqual(
		overviewRequest.schema,
		{ type: "object", additionalProperties: schemaRef("ExposureDataRequestDto") },
		"The backend spec changed the exposure overview request",
	);
	schemas.ExposureOverviewRequestDto = overviewRequest.schema;
	overviewRequest.schema = schemaRef("ExposureOverviewRequestDto");

	// UserController.GetSubordinatesThresholdStatus returns exactly these keys, or `{}` for a manager without
	// subordinates
	const thresholdSummary = jsonSchema(
		spec,
		"/api/users/{managerId}/subordinates/threshold-summary",
		"get",
		"response",
	);
	assert.deepEqual(
		thresholdSummary.schema,
		{ type: "object", additionalProperties: schemaRef("ExposureThresholdSummaryDto") },
		"The backend spec changed the threshold summary response",
	);
	schemas.ThresholdSummaryDto = {
		type: "object",
		properties: Object.fromEntries(
			["noise", "dust", "vibration", "total"].map((key) => [key, schemaRef("ExposureThresholdSummaryDto")]),
		),
	};
	thresholdSummary.schema = schemaRef("ThresholdSummaryDto");

	// A `Dictionary<ExposureType, DangerLevel>`, which has a key for each exposure type in the request. Orval ignores
	// `propertyNames`, so the keys are declared as optional properties. Unknown keys are stripped when parsing.
	const bucketProperties = at(schemas, "CombinedExposureBucketDto", "properties");
	assert.deepEqual(
		bucketProperties.exposureDangerLevels,
		{ type: "object", additionalProperties: schemaRef("DangerLevel") },
		"The backend spec changed CombinedExposureBucketDto.exposureDangerLevels",
	);
	bucketProperties.exposureDangerLevels = {
		type: "object",
		properties: Object.fromEntries(STRING_ENUMS.ExposureType.map((type) => [type, schemaRef("DangerLevel")])),
	};

	// Positional records, so missing properties are `null`. The backend ignores `userId` and uses the route parameter.
	for (const [name, property] of [
		["NoteDataRequestDto", "userId"],
		["ExposureDataRequestDto", "field"],
	]) {
		const schema = at(schemas, name);
		assert.ok(
			Array.isArray(schema.required) && schema.required.includes(property),
			`The backend spec no longer requires ${name}.${property}`,
		);
		schema.required = schema.required.filter((required) => required !== property);
	}

	// `NoteData.Time` is a required `DateTime`, and `[Required]` rejects `null` in requests
	for (const name of ["NoteDataDto", "NoteDataCreateDto"]) {
		const time = at(schemas, name, "properties", "time");
		assert.deepEqual(time.type, ["null", "string"], `The backend spec changed ${name}.time`);
		time.type = "string";
	}
}

function addFrontendRequirements(spec: unknown) {
	const schemas = at(spec, "components", "schemas");

	// Zod's `uuid()` only accepts RFC 9562 UUIDs, but the demo data uses GUIDs like 22222222-2222-2222-2222-222222222222
	let guids = 0;
	walk(spec, (node) => {
		if (node.format === "uuid") {
			delete node.format;
			node.pattern = GUID_PATTERN;
			guids++;
		}
	});
	assert.ok(guids > 0, "The backend spec no longer has UUIDs");

	// The backend allows users without a location, but the frontend needs one for every user
	for (const name of ["UserDto", "UserWithStatusDto"]) {
		const properties = at(schemas, name, "properties");
		assert.deepEqual(
			properties.location,
			{ oneOf: [{ type: "null" }, schemaRef("LocationDto")] },
			`The backend spec changed ${name}.location`,
		);
		properties.location = schemaRef("LocationDto");
		at(properties, "email").format = "email";
	}

	at(schemas, "HourDomainDto", "properties", "minHourUtc").minimum = 0;
	at(schemas, "HourDomainDto", "properties", "maxHourUtc").maximum = 23;

	for (const count of ["safe", "warning", "danger"]) {
		at(schemas, "ExposureThresholdSummaryDto", "properties", count).minimum = 0;
	}
}

const correctSpec: InputTransformerFn = (spec) => {
	correctBackendContract(spec);
	addFrontendRequirements(spec);
	return spec;
};

export default correctSpec;
